CREATE OR REPLACE PACKAGE BODY shipping_cost AS
  FUNCTION cost_for(p_order_total IN NUMBER) RETURN NUMBER IS
  BEGIN
    IF p_order_total >= freight_config.c_free_over THEN
      RETURN 0;
    ELSE
      RETURN 15.00;
    END IF;
  END cost_for;
END shipping_cost;
